using Aspire.Hosting.Testing;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.Extensions.AI.Evaluation.Reporting.Storage;

namespace MyApp.Evals;

[TestClass]
public sealed class EvalFixture
{
    private static DistributedApplication? _app;
    private static IChatClient? _chatClient;
    private static ReportingConfiguration? _reportingConfiguration;

    public static IChatClient ChatClient =>
        _chatClient ?? throw new InvalidOperationException("Call InitializeAsync first.");

    public static ReportingConfiguration ReportingConfiguration =>
        _reportingConfiguration ?? throw new InvalidOperationException("Call InitializeAsync first.");

    [AssemblyInitialize]
    public static async Task InitializeAsync(TestContext context)
    {
        var builder = await DistributedApplicationTestingBuilder.CreateAsync<Program>();
        _app = await builder.BuildAsync();
        await _app.StartAsync();

        _chatClient = _app.Services.GetRequiredService<IChatClient>();
        _reportingConfiguration = CreateReportingConfiguration(_chatClient);
    }

    [AssemblyCleanup]
    public static async Task CleanupAsync()
    {
        if (_app is not null)
        {
            await _app.StopAsync();
            await _app.DisposeAsync();
        }
    }

    private static ReportingConfiguration CreateReportingConfiguration(IChatClient chatClient)
    {
        var storageDir = Path.Combine(
            Path.GetDirectoryName(typeof(EvalFixture).Assembly.Location)!,
            "eval-results");

        var evaluators = new IEvaluator[]
        {
            new RelevanceEvaluator(),
            new CoherenceEvaluator(),
            new GroundednessEvaluator(),
        };

        var chatConfig = new ChatConfiguration(chatClient);

        return DiskBasedReportingConfiguration.Create(
            storageRootPath: storageDir,
            evaluators: evaluators,
            chatConfiguration: chatConfig);
    }
}

